    const c = []; for (let i = 0; i <= 30; i++) { const u = i / 30; c.push([(14 + u * 72) * U, (52 - 34 * u * u - 4 * Math.sin(u * 9) * (1 - u)) * U]); } part(c, .3, .85);
    if (d > .85) circle(86 * U, 18 * U, 2 * U * backOut(seg(d, .85, 1)), { fill: SM.glowGold, stroke: SM.chalk, lwPx: 1.5 });
