    for (let i = 0; i < 4; i++) { part([[cx - 29 * U, cy + (-10 + i * 6) * U], [cx - 6 * U, cy + (-10 + i * 6) * U]], .5 + i * .06, .6 + i * .06); part([[cx + 6 * U, cy + (-10 + i * 6) * U], [cx + 29 * U, cy + (-10 + i * 6) * U]], .62 + i * .06, .72 + i * .06); }
