  for (let i = 1; i < 11; i++) line([[mx - mw / 2 + i * mw / 11, my - mh / 2 + .12], [mx - mw / 2 + i * mw / 11, my + mh / 2 - .12]], { stroke: 'rgba(255,255,255,.07)', lw: .1 });
